pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 withdrawAmount) internal {
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        assertTrue(withdrawReverted == (withdrawAmount > 0));
    }

    function testFuzz_run(uint256 withdrawAmount) public {
        _run(withdrawAmount);
    }

    receive() external payable {}
}
